  "vidcfg.geminiOmniQuotaExceeded": "Entradas demais para o Gemini Omni: imagens + 2×vídeos deve ser ≤ 7 (atualmente {used}). O quadro inicial e cada imagem de referência contam como 1; cada vídeo de origem conta como 2. Remova algumas entradas antes de gerar.",
