  "proccfg.cameraSwitchHint": "Escolhe qual câmera mostra cada corte da edição de acordo com quem está falando — o som nunca muda. Conecte o EDL do Plano de edição à entrada EDL e um resultado de Transcrição com detecção de falantes à entrada Transcrição, e a saída EDL ao Apply EDL. Recurso da nuvem.",
