  "vidcfg.durationAuto": "Automática",
  "vidcfg.durationAutoHint": "Automática: o modelo escolhe a duração (a do clipe de origem ao editar um vídeo de referência). Os créditos são reservados para o clipe mais longo, e o excedente é reembolsado de acordo com a duração entregue.",
  "vidcfg.wan3Note": "O preço depende da duração e da resolução; o botão Executar mostra o preço da duração escolhida. O áudio ambiente é gerado com o clipe. “Adaptativo” segue a entrada conectada; texto para vídeo puro é renderizado em 16:9, a menos que uma proporção específica seja escolhida.",
  "vidcfg.wan3VideoRefLimits": "O Wan 3.0 exige que cada clipe de origem tenha de 1 a 15 s, que todos os clipes conectados somem no máximo 15 s e que a duração de entrada + a duração de saída fiquem em até 30 s. O provedor verifica esses limites quando a tarefa é executada, não antes do envio.",
  "vidcfg.wan3AudioRefLimits": "Cada referência de áudio deve ter de 1 a 15 s (verificado antes do envio da tarefa), e todo o áudio conectado deve somar no máximo 15 s.",
  "vidcfg.matchResSeam": "Usar a mesma resolução do vídeo de origem deixa a emenda mais limpa.",
  "vidcfg.sameSeedSimilar": "A mesma seed produz resultados parecidos. Deixe vazio para usar uma aleatória.",
  "vidcfg.veo31Audio": "O VEO 3.1 cria áudio com IA a partir do prompt. Desative para um vídeo sem som e depois use um nó que adicione áudio.",
  "vidcfg.veoAutoTranslateNote": "Os prompts são traduzidos automaticamente para o inglês antes de chegar ao VEO (ativado por padrão). Desative para manter os prompts exatamente como foram escritos — útil para prompts em outros idiomas ou quando a redação exata importa (ex.: a frase de fechamento do loop perfeito).",
  "vidcfg.veoAutoTranslateNoteShort": "Os prompts são traduzidos automaticamente para o inglês antes de chegar ao VEO (ativado por padrão). Desative para manter os prompts exatamente como foram escritos.",
  "vidcfg.worksBestSameFrames": "Funciona melhor quando o quadro inicial e o final usam a mesma imagem. Sem um quadro final, o algoritmo escolhe o melhor ponto de loop que encontrar, mas a emenda pode ficar visível.",
  "vidcfg.splitsScript": "Divide seu roteiro em prompts por segmento. Padrão: Claude Opus 4.7.",
  "vidcfg.connectVideoSlider": "Conecte um vídeo e abra a prévia dele para ativar o controle deslizante",
  "vidcfg.descSpeechToVideo": "Gera um vídeo de uma pessoa falando a partir de uma imagem e um áudio, com o Wan 2.2 Speech-to-Video. Conecte uma imagem de retrato, um áudio de fala e um prompt.",
