  "audiocfg.descAvatarInference": "Conecte um vídeo e uma faixa de áudio para substituir ou dublar a fala com sincronização labial de alta precisão por inferência de avatar. Cobrado por segundo de saída.",
  "audiocfg.descStudioGrade": "Conecte um vídeo (.mp4) e uma faixa de áudio (.wav) para uma sincronização labial com qualidade de estúdio. Cobrado por segundo de saída.",
  "audiocfg.descSyncSo": "Conecte um vídeo e uma faixa de áudio para dublar as imagens com o sync.so v3 (fal.ai). Cobrado por segundo de saída.",
  "audiocfg.descVolcengine": "Conecte um vídeo e uma faixa de áudio para dublar as imagens (Volcengine). A duração da saída acompanha o áudio. Cobrado por segundo.",
  "audiocfg.descVoiceExtractor": "Remove o ruído de fundo e extrai uma voz limpa de qualquer entrada de áudio. Conecte uma fonte de áudio (“Enviar áudio”, “Texto para fala” etc.) à entrada.",
  "audiocfg.hintSpeakerBoostDesc": "Amplifica a interpretação da origem. Mantenha em 0, a menos que queira mais drama — valores mais altos aumentam a latência e podem reduzir a estabilidade.",
  "audiocfg.hintSimilarityBoostDesc": "Aumenta a semelhança com a voz de destino (usa mais processamento, com leve latência). Ativado por padrão.",
  "audiocfg.hintSeedReproducible": "Fixe para obter uma saída reproduzível (mesma seed + mesma entrada + mesmas configurações). Deixe em branco para usar uma aleatória.",
  "audiocfg.hintDubCloneDesc": "Por padrão, a dublagem CLONA o falante original — ele fala o idioma de destino com a própria voz e o próprio sotaque. Marque esta opção para usar uma voz parecida, com som nativo.",
  "audiocfg.hintDubTranslate": "Traduz a fala para o idioma de destino. Conecte uma fonte de áudio à entrada.",
  "audiocfg.descVoiceDesign": "Gera uma nova voz a partir de uma descrição em linguagem natural e cria uma prévia em áudio com o texto informado.",
  "audiocfg.descForcedAlign": "Alinha o áudio a uma transcrição para gerar marcações de tempo por palavra. Conecte uma fonte de áudio à entrada.",
  "audiocfg.descRecast": "Os falantes são detectados automaticamente. A voz 1 substitui o primeiro falante a falar, a voz 2, o segundo, e assim por diante. Os falantes que excederem esta lista mantêm a voz original.",
  "audiocfg.hintPreservedMusicLevel": "Define o volume da música de fundo preservada em relação às vozes substituídas.",
  "audiocfg.hintRevoiceOffOn": "Desativado: mantém a base de música / efeitos sonoros sob a nova voz. Ativado: saída limpa, só com a voz.",
  "audiocfg.hintRevoicePre": "Substitui a voz pela voz selecionada, preservando a emoção, a cadência e o timing. Conecte ",
  "audiocfg.hintRevoiceMid": " na entrada para obter áudio na saída, ou ",
  "audiocfg.hintRevoicePost": " na entrada para redublar um clipe falado inteiro (você recebe o vídeo de volta com a nova faixa de áudio). Se os dois estiverem conectados, o vídeo tem prioridade e a entrada de áudio é ignorada.",
