  "tut.apOtherSlides": "Os outros nove slides",
  "tut.apCaptionLabel": "A legenda que ele escreveu",
  "tut.apPostCaption": "slide {n} de 10, feed quadrado",
  "tut.mrcRole1": "a pessoa",
  "tut.mrcRole2": "o chapéu",
  "tut.mrcRole3": "a pintura facial",
  "tut.mrcRole4": "a jaqueta",
  "tut.mrcRole5": "o lugar + a cor da camisa",
  "tut.mrcContrib1": "quem é a pessoa",
  "tut.mrcContrib3": "pintura facial, só na bochecha direita",
  "tut.mrcContrib5": "o lugar e a cor da camisa",
  "tut.mrcDefaultHint": "Passe o mouse sobre qualquer token rosa no prompt. A referência para a qual ele aponta se destaca à esquerda, e a função dela aparece aqui.",
  "tut.mrcHint1": "A pessoa da imagem 1, o lugar da imagem 5 e mais uma proibição explícita. Dizer o que não pegar é tão essencial quanto dizer o que pegar.",
  "tut.mrcHint2": "Um objeto da imagem 2 e mais uma instrução que nenhuma das cinco fontes fornece.",
  "tut.mrcHint3": "Um detalhe da imagem 3, restrito a um lado do rosto. A outra bochecha é descrita como limpa.",
  "tut.mrcHint4": "A peça de roupa inteira da imagem 4, reproduzida com exatidão.",
  "tut.mrcHint5": "Só um atributo. A cor da camisa vem da imagem 5, não a camisa em si.",
  "tut.mrcAddRefsTitle": "Adicione suas referências",
  "tut.mrcAddRefsSub": "A ordem define o número do token",
  "tut.mrcWritePromptTitle": "Escreva o prompt",
  "tut.mrcWritePromptSub": "Passe o mouse sobre um token para ver o que ele puxa",
  "tut.mrcGenerateSub": "Uma imagem, cinco fontes",
  "tut.mrcMakeItYours": "Faça a sua versão",
  "tut.mrcClosing1Body": "Troque qualquer upload por uma imagem sua e execute novamente. Os tokens continuam funcionando, porque apontam para posições, não para arquivos.",
  "tut.mrcClosing2Eyebrow": "Se algo sair errado",
  "tut.mrcClosing2Body": "Confira a ordem das referências antes de reescrever o prompt. O número indica a posição, não o nome.",
  "tut.mrcClosing3Eyebrow": "Para testar uma referência",
  "tut.mrcClosing3Body": "Mude-a, execute novamente, compare. Uma variável por vez: esse é todo o método.",
  "tut.pnLesson1Title": "Conheça o nó “Pessoa”",
  "tut.pnLesson1Sub": "As escolhas viram um prompt escrito",
  "tut.pnLesson1Body": "Escolha os atributos e o nó escreve o prompt do personagem para você. Abra o “Prompt final” no nó “Gerar imagem” para ver exatamente o que é enviado ao modelo.",
  "tut.pnLesson1Callout": "Experimente: mude um atributo e veja o prompt se atualizar. Tudo o que você digitar no campo “Prompt” é combinado com ele.",
  "tut.pnLesson2Title": "Mesmo nó, outro personagem",
  "tut.pnLesson2Sub": "Mude as escolhas e tudo muda",
  "tut.pnLesson2Body": "O mesmo nó “Pessoa”, atributos diferentes, um resultado completamente diferente. A etapa 1 gerou um street style editorial; aqui, o mesmo nó gera um retrato intimista em um ambiente interno.",
  "tut.pnLesson3Title": "Combine nós para controlar a cena inteira",
  "tut.pnLesson3Sub": "Cena, enquadramento, clima, personagem",
  "tut.pnLesson3Body": "A mesma “Pessoa”, agora com “Fundo de estúdio”, “Enquadramento” e “Clima” em camadas. Cada nó adiciona a própria descrição ao “Prompt final”.",
  "tut.pnLesson3Closing": "Mesmo modelo, uma foto totalmente diferente. Troque um bloco e execute novamente.",
  "tut.pnOrderScene": "cena",
  "tut.pnOrderFraming": "enquadramento",
  "tut.pnOrderMood": "clima",
  "tut.pnOrderCharacter": "personagem",
  "tut.pnRailStep1Sub": "Sete escolhas viram um prompt escrito",
  "tut.pnRailStep3Title": "Combine nós para controlar a cena",
  "tut.pnRailStep3Sub": "“Fundo de estúdio”, “Enquadramento” e “Clima” por cima",
  "tut.pnNoteEyebrow": "O padrão",
  "tut.pnNoteBody": "Monte imagens com blocos modulares. Troque qualquer nó para iterar rápido.",
  "tut.iedNavyName": "Jaqueta azul-marinho",
  "tut.iedSubWritten": "Uma instrução escrita",
  "tut.iedNavyWhy": "O tipo mais simples de edição: diga o que mudar e o que deixar como está. É justamente dizer o que você quer manter que impede o modelo de redesenhar o rosto junto com a jaqueta.",
  "tut.iedGoldenName": "Hora dourada",
  "tut.iedSubLighting": "Controlada por um nó “Iluminação”",
  "tut.iedGoldenWhy": "Nenhum prompt. O nó “Iluminação” guarda a escolha, e a edição a lê — então mudar a iluminação da foto é escolher uma opção em um menu, não acertar uma frase.",
  "tut.iedTealName": "Azul-petróleo e laranja",
  "tut.iedSubColor": "Controlado por um nó “Cor / look”",
  "tut.iedTealWhy": "Um tratamento de cor, não uma repintura. A mesma imagem com um visual de cinema aplicado — o tipo de mudança que você descreveria mal em três linhas de prompt.",
  "tut.iedAnimeName": "Anime, pintado",
  "tut.iedSubTwoStyles": "Dois nós “Estilo” ao mesmo tempo",
  "tut.iedAnimeWhy": "Dois nós “Estilo” alimentam esta edição, e o resultado mistura os dois. O estilo não é um espaço único — combine vários e você terá um visual que nenhum deles descreve sozinho.",
  "tut.iedAtomicName": "Era atômica, anos 1950",
  "tut.iedSubEra": "Controlada por um nó “Época”",
  "tut.iedAtomicWhy": "Uma época traz figurino, paleta e película juntos. Esta edição também usa um modelo diferente das vizinhas, o que é uma escolha de cada nó, não uma configuração do canvas inteiro.",
  "tut.iedCyberName": "Cyberpunk",
  "tut.iedSubStyle": "Controlado por um nó “Estilo”",
  "tut.iedCyberWhy": "O mesmo nó “Estilo” da edição de anime, com outro valor. Um único tipo de nó cobre o catálogo inteiro, então testar outro visual leva um clique.",
  "tut.ied85mmName": "Retrato em 85 mm",
  "tut.iedSubLens": "Controlado por um nó “Lente”",
  "tut.ied85mmWhy": "Óptica, não conteúdo. A distância focal muda a compressão e a profundidade de campo — o assunto continua intacto, e a fotografia vira outra fotografia.",
  "tut.iedNoBgName": "Fundo removido",
  "tut.iedSubNoSettings": "Nenhuma configuração",
  "tut.iedNoBgWhy": "Nada para configurar e nada para escrever. O nó recorta o assunto sobre fundo transparente, pronto para ser colocado sobre qualquer coisa.",
  "tut.iedTokyoName": "Tóquio à noite",
  "tut.iedTokyoWhy": "Trocar o fundo exige duas coisas ao mesmo tempo: o novo lugar e a iluminação do assunto ajustada a ele. Peça só a primeira e o aspecto de recorte denuncia a montagem.",
  "tut.iedHeadline": "Entra uma imagem. Saem nove edições diferentes.",
  "tut.iedSubline": "Todas as edições leem o mesmo original, então nada se acumula e nada se degrada. Clique em qualquer resultado para ver exatamente o que o produziu.",
  "tut.iedChipEdits": "9 edições",
  "tut.iedChipSharedOriginal": "1 original compartilhado",
  "tut.iedChipNonDestructive": "nada é destrutivo",
  "tut.iedInSub": "Gerado uma vez e nunca mais alterado",
  "tut.iedOutSub": "Clique em um para ver o que o gerou",
  "tut.iedCriticLine": "Avalia o original antes de você gastar qualquer coisa com edições.",
  "tut.iedNoSettings": "Sem configurações",
  "tut.ccvHeadline": "Entra um quadro. Saem dez ângulos do mesmo momento.",
  "tut.ccvSubline": "Personagem, figurino, local e luz nunca mudam. Só a câmera muda. Você vê a lista de tomadas antes de gastar qualquer coisa e pode reescrever qualquer linha dela.",
  "tut.ccvChipNodes": "6 nós, não 25",
  "tut.ccvChipCuttable": "montável em sequência",
