  "tut.ccvInSub": "Uma imagem. Esta é a cena.",
  "tut.ccvRefPromptEyebrow": "Prompt de referência",
  "tut.ccvBriefEyebrow": "O briefing de cobertura · edite para mudar o plano",
  "tut.ccvBriefRule1": "Ordem real de cobertura: plano geral, dois planos médios, dois primeiros planos, plano sobre o ombro, contraplano, plano detalhe, ângulo dinâmico, perfil.",
  "tut.ccvBriefRule2": "Um ângulo de câmera por linha. Nunca combine dois termos de ângulo.",
  "tut.ccvBriefRule3": "Posição da câmera, não movimento. O movimento é adicionado depois.",
  "tut.ccvBriefRule4": "A direção na tela se mantém constante, para que os cortes não saltem.",
  "tut.ccvBriefRule5": "Deixe espaço para respirar. Cada quadro precisa funcionar como quadro inicial de uma animação.",
  "tut.ccvListTitle": "A lista de tomadas",
  "tut.ccvListSub": "{count} linhas, editáveis antes de qualquer gasto",
