  "tut.promptEyebrow": "PROMPT",
  "tut.ocHeadline": "Duas imagens. Cinco receitas. Sem máscaras, sem camadas.",
  "tut.ocSubline": "Todas as receitas abaixo leem as mesmas duas fontes. O que muda é qual parte de cada uma você cita e com qual número. Essa é toda a técnica.",
  "tut.ocChipNoMask": "nenhuma máscara",
  "tut.ocInTitle": "Duas fontes",
  "tut.ocInSub": "Uma gerada, uma enviada",
  "tut.ocRoleGenerated": "foto de passarela gerada",
  "tut.ocRoleUploaded": "foto de estúdio enviada",
  "tut.ocSameTwoEyebrow": "AS MESMAS DUAS, SEMPRE",
  "tut.ocSameTwoBody": "As cinco receitas estão conectadas a estas duas imagens. Nada é reenviado e nada é editado entre as execuções.",
  "tut.ocRecipesTitle": "Cinco receitas",
  "tut.ocRecipesSub": "Uma linha de prompt cada",
  "tut.ocRecipesMeta": "CLIQUE EM UMA",
  "tut.ocTakesEyebrow": "O QUE ESTA RECEITA USA",
  "tut.ocNodeEyebrow": "NÓ",
  "tut.ocR1Name": "Rosto de uma, corpo da outra",
  "tut.ocR1OutTitle": "Um corpo, outro rosto",
  "tut.ocR1OutSub": "Receita 1 · as duas referências com qualificador",
  "tut.ocR1LessonKind": "O PONTO DE PARTIDA",
  "tut.ocR1Lesson": "Duas referências com qualificador constroem uma única pessoa a partir de duas imagens. Nenhuma delas chega inteira.",
  "tut.ocR1Note1": "Pose, porte físico e enquadramento. O rosto não é usado.",
  "tut.ocR1Note2": "Só o rosto é transferido.",
  "tut.ocR2Name": "Troque a ordem, troque o resultado",
  "tut.ocR2OutTitle": "A mesma receita, invertida",
  "tut.ocR2OutSub": "Receita 2 · números trocados",
  "tut.ocR2LessonKind": "O OBJETIVO DE TODO O TEMPLATE",
  "tut.ocR2Lesson": "Os mesmos qualificadores, números trocados. Qual imagem é a 1 e qual é a 2 decide quem aparece na foto.",
  "tut.ocR2Note1": "Agora a segunda fonte fornece o corpo.",
  "tut.ocR2Note2": "E a primeira fornece só o rosto.",
  "tut.ocR3Name": "Mantenha o palco, troque a estrela",
  "tut.ocR3OutTitle": "Mesmo lugar, outra pessoa",
  "tut.ocR3OutSub": "Receita 3 · qualificador background",
  "tut.ocR3LessonKind": "OUTRO QUALIFICADOR",
  "tut.ocR3Lesson": "O qualificador background pede o lugar sem quem está nele. Útil quando o local é o que você quer manter.",
  "tut.ocR3Note1": "A passarela e a iluminação dela, sem a modelo.",
  "tut.ocR3Note2": "A pessoa que agora está nela.",
  "tut.ocR4Name": "Da passarela para o estúdio",
  "tut.ocR4OutTitle": "Mesma pessoa, outro lugar",
  "tut.ocR4OutSub": "Receita 4 · o espelho da receita 3",
  "tut.ocR4LessonKind": "LEIA A PREPOSIÇÃO",
  "tut.ocR4Lesson": "O qualificador settings é o inverso da receita acima: mantém a pessoa e a leva para outro lugar. É a palavra in que faz o posicionamento.",
  "tut.ocR4Note1": "O assunto, transferido por inteiro.",
  "tut.ocR4Note2": "O fundo do estúdio e a luz dele.",
  "tut.ocR5Name": "A jaqueta dela, o estúdio dela, a sua modelo",
  "tut.ocR5OutTitle": "Três partes, duas imagens",
  "tut.ocR5OutSub": "Receita 5 · dois qualificadores de uma só fonte",
  "tut.ocR5LessonKind": "EMPILHAMENTO",
  "tut.ocR5Lesson": "A mesma fonte pode ser citada duas vezes com qualificadores diferentes. Aqui, a imagem 2 fornece uma peça de roupa e um local, em uma única linha.",
  "tut.ocR5Note1": "O assunto.",
  "tut.ocR5Note2": "Uma peça de roupa, extraída isoladamente.",
  "tut.ocR5Note3": "E a sala onde ela foi fotografada.",
  "tut.ocRecipeAsWritten": "Receita {n} · como está escrita no nó",
  "tut.ocLessonKindOther": "OUTRA COMBINAÇÃO",
  "tut.ocLessonOther": "Leia o prompt: qual fonte é citada, qual parte dela e com qual número.",
  "tut.ocAddsUpEyebrow": "COMO TUDO SE SOMA",
  "tut.ocResultChip": "O RESULTADO",
  "tut.ocResultCaption": "uma imagem, sem máscaras",
