  "tut.regMrcTitle": "Controle com várias referências",
  "tut.regMrcSummary": "Cinco imagens de origem, uma imagem gerada. Aponte para uma imagem em vez de descrevê-la.",
  "tut.regMrcStep1Sub": "Cinco uploads em um único conector “Referências”",
  "tut.regMrcStep2Sub": "Aponte para posições com @image:N",
  "tut.regMrcStep4Sub": "Troque uma imagem, execute novamente, compare",
  "tut.regWdSummary": "Uma frase virou imagem, a imagem virou movimento e uma narração amarrou tudo. Este canvas é uma execução concluída.",
  "tut.regWdStep2Sub": "Z-Image, a primeira coisa que vale a pena executar",
  "tut.regWdStep3Sub": "Seedance 2 Fast, 5 segundos",
  "tut.regWdStep4Sub": "Uma segunda cadeia, executada em paralelo",
  "tut.regWdStep5Sub": "Vídeo e voz mesclados",
  "tut.regPnTitle": "Primeiros passos com o nó “Pessoa”",
  "tut.regPnSummary": "Escolha atributos em menus suspensos e o nó escreve o prompt do personagem para você. Três execuções, de um único nó até uma combinação completa.",
  "tut.regPnChip": "3 execuções",
  "tut.regSunoTitle": "Criando música com nós",
  "tut.regSunoSummary": "Você não escreve a descrição da música. Escolhe as opções, e os nós a escrevem por você.",
  "tut.regSunoChip": "7 execuções",
  "tut.regSunoNoteEyebrow": "Como usar este tutorial",
  "tut.regSunoNoteBody": "Percorra as execuções. Cada uma muda exatamente uma coisa em relação à anterior, então a diferença que você ouve é a opção que mudou.",
  "tut.regSunoStep1Title": "Escolha opções nos nós de estilo",
  "tut.regSunoStep1Sub": "Gênero, clima, instrumentação, voz",
  "tut.regSunoStep2Title": "Envie as escolhas para o nó “Gerar com Suno”",
  "tut.regSunoStep2Sub": "As escolhas viram a descrição do estilo",
  "tut.regSunoStep3Title": "Receba uma faixa pronta",
  "tut.regSunoStep3Sub": "Ouça e depois mude uma opção",
  "tut.regApTitle": "Piloto automático para redes sociais",
  "tut.regApSummary": "Cole uma ideia. Sete nós a dividem em slides, desenham uma imagem para cada um, escrevem a legenda e publicam.",
  "tut.regApStep1Title": "Forneça um bloco de texto",
  "tut.regApStep1Sub": "Nada mais para preencher",
  "tut.regApStep2Title": "Ele escreve e desenha dez slides",
  "tut.regApStep2Sub": "Texto e uma imagem para cada slide",
  "tut.regApStep3Title": "Ele escreve a legenda e publica",
  "tut.regApStep3Sub": "Formatado para o feed e depois publicado",
  "tut.regIedTitle": "Primeiros passos na edição de imagens",
  "tut.regIedSummary": "Uma imagem é gerada uma vez, e nove edições independentes leem esse mesmo original. Nada se acumula, então nada se degrada.",
  "tut.regIedNoteEyebrow": "É uma ramificação, não uma sequência",
  "tut.regIedNoteBody": "Todas as edições leem o original diretamente. Mude uma e as outras oito não são afetadas — essa é toda a ideia.",
  "tut.regIedStep1Sub": "Gerado uma vez e depois avaliado",
  "tut.regIedStep2Title": "Nove edições, uma fonte",
  "tut.regIedStep2Sub": "Cada uma lê a mesma imagem",
  "tut.regIedStep3Title": "Acompanhe qualquer resultado",
  "tut.regIedStep3Sub": "Clique em uma miniatura para ver o que a gerou",
  "tut.regCcvTitle": "Cobertura de câmera — um quadro, dez ângulos",
  "tut.regCcvSummary": "Entra um quadro de referência, saem dez tomadas da mesma cena. Só a câmera muda — um plano de cobertura de diretor, pronto para montar, a partir de uma única imagem.",
  "tut.regCcvChip": "10 tomadas",
  "tut.regCcvNoteEyebrow": "A alavanca é a lista",
  "tut.regCcvNoteBody": "Um nó de imagem, dez linhas. A lista o ramifica, e assim dez tomadas custam seis nós, não vinte e cinco — e editar uma linha refaz um único ângulo.",
  "tut.regCcvStep1Sub": "Uma imagem e o briefing que rege o plano",
  "tut.regCcvStep2Sub": "Dez linhas que você pode ler — e reescrever — antes de qualquer gasto",
  "tut.regCcvStep3Sub": "Dez tomadas de um mesmo momento, a partir de um nó de imagem",
  "tut.regOcTitle": "Um personagem, qualquer cena",
  "tut.regOcSummary": "Duas imagens de origem, cinco receitas de uma linha, sem máscaras e sem camadas. O que muda entre os resultados é qual parte de cada fonte você cita — e com qual número.",
  "tut.regOcChip": "5 receitas",
  "tut.regOcNoteEyebrow": "Leia os números, não as imagens",
  "tut.regOcNoteBody": "{image:1} e {image:2} são posições na lista de referências — a ordem em que as fontes foram conectadas —, e não os nomes dos nós. A receita 2 é a receita 1 com os números trocados, e essa é toda a lição.",
  "tut.regOcStep1Sub": "Uma gerada, uma enviada — {image:1} e {image:2}",
  "tut.regOcStep2Sub": "Clique em uma: o que ela usa de cada fonte e o que ensina",
  "tut.regOcStep3Sub": "A imagem e como as partes emprestadas a compõem",
  "tut.regUwTitle": "Gigantes submarinos",
  "tut.regUwSummary": "Escreva oito cenas. Cada uma vira uma imagem e depois uma tomada de cinco segundos, montadas com música e publicadas como reel.",
  "tut.regUwStep1Title": "Escreva oito cenas",
  "tut.regUwStep1Sub": "Um parágrafo para cada",
  "tut.regUwStep2Title": "Imagens fixas, depois movimento",
  "tut.regUwStep2Sub": "Cada cena ancorada na anterior",
